parameters.jsCode:
return items.map(item => {
  // A bemeneti struktúra alapján a szöveg kinyerése
  // A példád alapján: content tömb első elemének 'text' mezője
  const rawText = item.json.content?.[0]?.text || item.json.text || "";

  // Markdown kódblokk jelölők (```json és ```) eltávolítása regex segítségével
  const cleanJsonString = rawText.replace(/```json\s*|```/g, '').trim();

  try {
    // String konvertálása valódi JSON objektummá
    const parsedData = JSON.parse(cleanJsonString);

    // Visszatérés a tiszta adatstruktúrával
    return {
      json: parsedData
    };

  } catch (error) {
    // Hibakezelés, ha az LLM nem valid JSON-t küldött
    return {
      json: {
        error: "JSON parse failed",
        message: error.message,
        originalInput: rawText
      }
    };
  }
});

